<script>
 import { onMount, tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { phoneSession, phoneCards, phoneEndpoint, virtualPhoneDevice, phoneAvailability } from './phone-family-state.js';
 import { phoneMenus } from './phone-family-commands.js';
 import { createPhoneNativeView } from './phone-family-native-view.js';
 import { contactName } from './contacts-state.js';
 import './phone-family.css';
 let { state: devicePhoneSurfaceState, profile, windowId, window, execute, registerView, available = true, active = true, controls = {}, shared, getSceneTime, mirroring = false } = $props();
 let root, originalRoot, originalState, mounted = false;
 let error = $state(''), code = $state('');
 const session = $derived(phoneSession(devicePhoneSurfaceState, windowId));
 const account = $derived(shared.messages.account);
 const device = $derived(virtualPhoneDevice(shared.bluetooth));
 const authorized = $derived(!mirroring || session?.authenticated && account.signedIn && shared.bluetooth.powered && device?.available && device.paired && device.connected);
 const cards = $derived(phoneCards(shared.contacts, session?.query ?? ''));
 const endpoint = $derived(session ? phoneEndpoint(shared.contacts, session) : null);
 const recent = $derived(shared.calls.calls.filter(call => !session?.query || call.participants.some(row => `${row.name} ${row.address}`.toLowerCase().includes(session.query.toLowerCase()))).toReversed());
 const currentCall = $derived(shared.calls.calls.find(row => row.id === session?.callId) ?? shared.calls.calls.find(row => !['ended', 'failed'].includes(row.status)));
 const activeCall = $derived(shared.calls.calls.find(row => !['ended', 'failed'].includes(row.status)));
 const photos = $derived(shared.photos.items.filter(row => row.inLibrary && !row.hidden && !row.deletedAt));
 const photo = $derived(photos.find(row => row.id === session?.photoId));
 const conversation = $derived(shared.messages.conversations.find(row => row.id === session?.conversationId));
 const menus = $derived(phoneMenus(profile, devicePhoneSurfaceState, windowId, mirroring));
 const disclosure = $derived(phoneAvailability(profile, mirroring).disclosure);
 const profileId = $derived(typeof profile === 'string' ? profile : profile.id);
 const windows = $derived(profileId.startsWith('windows'));
 const classic = $derived(/high-sierra|mojave/.test(profileId));
 const prefix = $derived(mirroring ? 'mirroring' : 'phone');
 const time = $derived(new Date(getSceneTime?.() ?? controls.sceneTime ?? shared.calls.runtime.lastTime).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: 'UTC' }));
 const own = () => mounted && available && root === originalRoot && devicePhoneSurfaceState === originalState && !!session && root?.isConnected && !root.closest('[hidden],[inert]');
 const golden = $derived(profileId.includes('golden-gate'));
 const posterCard = $derived(shared.contacts.contacts.find(card => card.id === currentCall?.participants[0]?.contactId));
 async function command(suffix, payload = {}) { if (!own()) return; const source = root, graph = devicePhoneSurfaceState; try { const result = await execute(`${prefix}.${suffix}`, { windowId }, payload); if (own() && root === source && devicePhoneSurfaceState === graph) error = result?.status === 'rejected' || result?.status === 'unavailable' ? result.error?.message ?? result.message ?? 'The actual source is unavailable.' : ''; return result; } catch (cause) { if (own() && root === source && devicePhoneSurfaceState === graph) error = cause.message; } }
 function input(suffix, key, event) { const node = event.currentTarget, value = node.value; command(suffix, { [key]: value }).then(() => { if (own() && node.isConnected && root.contains(node) && node.value === value) node.value = session[key] ?? ''; }); }
 function favoriteCard(favorite) { return phoneCards(shared.contacts).find(card => card.id === favorite.contactId && card.phones.some(row => row.value === favorite.address)); }
 function chooseFavorite(favorite) { const card = favoriteCard(favorite); if (card) command('contact.select', { contactId: card.id, endpointIndex: card.phones.findIndex(row => row.value === favorite.address) }); }
 async function preference(key, value) { return command('preferences.set', { values: { ...shared.calls.preferences, [key]: value } }); }
 async function menuItem(item) { if (!item.enabled) return; await command('menu.close'); if (!own()) return; return command(item.request.command.slice(prefix.length + 1), item.request.payload); }
 onMount(() => { originalRoot = root; originalState = devicePhoneSurfaceState; mounted = true; const facade = createPhoneNativeView({ getRoot: () => root, getState: () => devicePhoneSurfaceState, windowId, available: own, tick, getSession: () => phoneSession(devicePhoneSurfaceState, windowId) }); registerView?.(windowId, facade); return () => { mounted = false; facade.destroy(); registerView?.(windowId, null, facade); }; });
 $effect(() => { if (mirroring && session?.authenticated && (!account.signedIn || !shared.bluetooth.powered || !device?.available || !device.paired || !device.connected) && mounted) command('lock'); });
</script>
<section bind:this={root} class="device-family" class:mirror={mirroring} class:windows class:classic class:golden class:inactive={!active} data-device-window={windowId} aria-label={mirroring ? 'iPhone Mirroring local authored phone' : 'Phone local calls'}>
 <header class="device-title" data-window-drag>
  {#if !windows}<WindowControls {...controls} {active} onclose={() => command('window.close')} />{/if}
  <strong>{mirroring ? device?.name ?? 'iPhone Mirroring' : 'Phone'}</strong>
  {#if mirroring}<button data-device-control="home" aria-label="Home Screen" onclick={() => command('tab.set', { tab: 'home' })} disabled={!authorized}>⌂</button><button data-device-control="lock" aria-label="Lock authored iPhone" onclick={() => command('lock')}>▣</button>{/if}
  {#if windows}<button data-device-control="close" aria-label="Close window" onclick={() => command('window.close')}>×</button>{/if}
 </header>
 <nav class="device-menus" aria-label="Application menus">{#each menus as menu}<div><button data-device-control={'menu:' + menu.id} aria-haspopup="menu" aria-expanded={session?.menu === menu.id} onclick={() => command(session?.menu === menu.id ? 'menu.close' : 'menu.open', session?.menu === menu.id ? {} : { menuId: menu.id })}>{menu.label}</button>{#if session?.menu === menu.id}<div class="device-menu" role="menu" aria-label={menu.id}>{#each menu.items as item}<button role="menuitem" disabled={!item.enabled} data-device-control={'item:' + item.id} onclick={() => menuItem(item)}>{item.label}</button>{/each}</div>{/if}</div>{/each}</nav>
 {#if session}
 {#if mirroring && !authorized}
 <div class="device-setup" data-device-area="setup">
  <div class="phone-outline"><span></span>⌁</div><h1>Your iPhone, on your desktop.</h1>
  <p>Connect the authored <b>{device?.name ?? 'Studio iPhone'}</b> fixture. No real iPhone, Bluetooth hardware, Apple login or remote screen is accessed.</p>
  <dl><dt>Shared scene account</dt><dd>{account.name} · {account.signedIn ? 'Signed in' : 'Signed out — sign in using FaceTime/Teams account settings'}</dd><dt>Scene Bluetooth</dt><dd>{shared.bluetooth.powered ? 'On' : 'Off — enable in scene Bluetooth'}</dd><dt>Device</dt><dd>{!device ? 'Missing original fixture' : !device.available ? 'Unavailable' : !device.paired ? 'Not paired' : !device.connected ? 'Paired, disconnected' : 'Paired and connected'} {device?.batteryPercent ?? ''}{device ? '%' : ''}</dd></dl>
  <button data-device-control="shared-account" onclick={() => command('account.open')}>Manage Shared Account…</button>
  {#if !device?.paired}<button class="primary" data-device-control="pair" onclick={() => command('device.pair')} disabled={!device?.available || !shared.bluetooth.powered}>Pair Studio iPhone…</button>{:else if !device.connected}<button class="primary" data-device-control="connect" onclick={() => command('device.connect')} disabled={!device.available || !shared.bluetooth.powered}>Connect</button>{/if}
  <form onsubmit={event => { event.preventDefault(); command('authenticate', { code }); }}><label>Fictional session passcode <input data-device-control="code" aria-label="Fictional session passcode" type="password" inputmode="numeric" maxlength="6" bind:value={code} autocomplete="off" /></label><button class="primary" data-device-control="authorize" disabled={!device?.connected || !account.signedIn || code.length !== 6}>Authorize Local Session</button></form>
  <small>Authored demo passcode: <b>482316</b>. Authorization expires when the window closes or a saved scene is restored. Pairing confirmation uses the original scene Bluetooth sheet.</small>
 </div>
 {:else}
 <div class="device-workspace">
  {#if !mirroring}<aside class="phone-sidebar"><label class="device-search">⌕ <input data-device-control="search" aria-label="Search contacts and recents" value={session.query} maxlength="4096" oninput={event => input('search', 'query', event)} /></label>{#each ['recents','favorites','contacts','keypad','settings'] as tab}<button data-device-control={'tab:' + tab} class:selected={session.tab === tab} onclick={() => command('tab.set', { tab })}><span>{({ recents: '◷', favorites: '★', contacts: '♙', keypad: '⠿', settings: '⚙' })[tab]}</span>{tab[0].toUpperCase() + tab.slice(1)}</button>{/each}<small>{account.name}<br />{account.signedIn ? 'Shared account signed in' : 'Shared account signed out'}</small></aside>{/if}
  <main class="device-content" data-device-area="content" class:phone-screen={mirroring}>
   {#if mirroring}<div class="phone-status"><b>{time}</b><span>Scene · {device?.batteryPercent}% ▰</span></div><div class="dynamic-island"></div>{/if}
   {#if golden && !mirroring}<div class="phone-favorite-strip">{#each session.favorites as favorite}{@const card = favoriteCard(favorite)}{#if card}<button data-device-control={'quick-favorite:' + card.id + ':' + favorite.address} onclick={() => chooseFavorite(favorite)}><span class="avatar">{contactName(card, shared.contacts.preferences).slice(0,1)}</span><small>{contactName(card, shared.contacts.preferences)}</small></button>{/if}{/each}<button data-device-control="show-keypad" onclick={() => command('tab.set',{tab:'keypad'})} aria-label="Show keypad">⠿</button></div>{/if}
   {#if session.tab === 'home'}
    <div class="authored-home"><h2>{device?.name}</h2><p>Authored phone · same scene data</p><div class="home-grid">{#each [{tab:'recents',symbol:'☎',label:'Phone',color:'#29b74d'},{tab:'contacts',symbol:'♙',label:'Contacts',color:'#ab8d68'},{tab:'messages',symbol:'▤',label:'Messages',color:'#28bb50'},{tab:'photos',symbol:'✿',label:'Photos',color:'#e98177'}] as app}<button data-device-control={'app:' + app.tab} onclick={() => command('tab.set', { tab: app.tab })}><span style:background={app.color}>{app.symbol}</span>{app.label}</button>{/each}</div></div>
   {:else if session.tab === 'contacts' || session.tab === 'favorites'}
    <h1>{session.tab === 'favorites' ? 'Favorites' : 'Contacts'}</h1>
    {#if mirroring}<input class="phone-search" data-device-control="search" aria-label="Search contacts" placeholder="Search" value={session.query} oninput={event => input('search','query',event)} />{/if}
    <div class="phone-columns"><div class="phone-list">
     {#if session.tab === 'favorites'}{#each session.favorites as favorite}{@const card = favoriteCard(favorite)}{#if card}<button data-device-control={'favorite:' + card.id + ':' + favorite.address} class:selected={endpoint?.address === favorite.address && endpoint?.card === card} onclick={() => chooseFavorite(favorite)}><span class="avatar">{contactName(card, shared.contacts.preferences).slice(0,1)}</span><span><b>{contactName(card, shared.contacts.preferences)}</b><small>{favorite.address}</small></span></button>{/if}{/each}{#if !session.favorites.some(favorite => favoriteCard(favorite))}<p>No selected favorites. Choose a contact and add its exact phone endpoint.</p>{/if}
     {:else}{#each cards as card}<div class="contact-row"><b>{contactName(card, shared.contacts.preferences)}</b>{#each card.phones as phone, index}<button data-device-control={'contact:' + card.id + ':' + index} class:selected={session.contactId === card.id && session.endpointIndex === index} onclick={() => command('contact.select', { contactId: card.id, endpointIndex: index })}>{phone.label} <span>{phone.value}</span></button>{/each}{#if !card.phones.length}<small>No phone endpoints — edit in Contacts</small>{/if}</div>{/each}{#if !cards.length}<p>No matching source contacts.</p>{/if}{/if}
    </div>{#if endpoint}<div class="contact-detail"><span class="large-avatar">{endpoint.name.slice(0,1)}</span><h2>{endpoint.name}</h2><p>{endpoint.endpoint.label}: {endpoint.address}</p><div class="actions"><button class="call-button" data-device-control="dial-contact" disabled={!account.signedIn} onclick={() => command('dial')}>☎ Call</button><button data-device-control="message-contact" onclick={() => command('message')}>Message</button><button data-device-control="favorite-toggle" onclick={() => command('favorite.toggle')}>{session.favorites.some(row => row.contactId === endpoint.card.id && row.address === endpoint.address) ? '★ Remove Favorite' : '☆ Add Favorite'}</button><button data-device-control="block-contact" onclick={() => command('block')}>Block endpoint</button></div><small>Source card {endpoint.card.id}, revision {endpoint.card.revision}. Literal endpoint is routed through {windows ? 'Teams local Calls' : 'FaceTime local Calls'}.</small></div>{/if}</div>
   {:else if session.tab === 'keypad'}
    <h1>Keypad</h1><div class="dialpad"><input data-device-control="digits" aria-label="Phone number" value={session.digits} maxlength="128" oninput={event => input('digits.set','digits',event)} /><div>{#each ['1','2','3','4','5','6','7','8','9','*','0','#'] as digit}<button data-device-control={'digit:' + digit} onclick={() => command('digits.set', { digits: session.digits + digit })}><b>{digit}</b><small>{({2:'ABC',3:'DEF',4:'GHI',5:'JKL',6:'MNO',7:'PQRS',8:'TUV',9:'WXYZ',0:'+'})[digit] ?? ' '}</small></button>{/each}</div><div class="dial-actions"><button class="call-button" data-device-control="dial" disabled={!session.digits.trim() || !account.signedIn} onclick={() => command('dial')}>☎ Call</button><button data-device-control="backspace" onclick={() => command('digits.set',{digits:session.digits.slice(0,-1)})}>⌫</button></div></div>
   {:else if session.tab === 'recents'}
    <div class="phone-recents-layout"><div class="phone-recents-main">
    <h1>Recents</h1><div class="phone-list recent-list">{#each recent as call}<button data-device-control={'recent:' + call.id} class:selected={session.callId === call.id} onclick={() => command('recent.select', { callId: call.id })}><span class="recent-icon">{call.direction === 'incoming' ? '↙' : '↗'}</span><span><b>{call.participants.map(row => row.name).join(', ')}</b><small>{call.participants.map(row => row.address).join(', ')} · {call.kind} · {call.status}</small></span><time>{new Date(call.createdAt).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'})}</time></button>{/each}{#if !recent.length}<p>No actual calls yet. Select a contact or use the keypad.</p>{/if}</div>{#if session.callId}<button class="call-button" data-device-control="redial" onclick={() => command('dial')} disabled={!account.signedIn}>☎ Call selected endpoint</button>{/if}
    </div>{#if golden && !mirroring && currentCall}<aside class="phone-contact-poster">{#if posterCard?.photo.kind === 'image'}<img src={posterCard.photo.value} alt={currentCall.participants[0].name} />{:else}<span class="poster-initial">{currentCall.participants[0].name.slice(0,1)}</span>{/if}<h2>{currentCall.participants[0].name}</h2><p>{currentCall.participants[0].address}</p><div class="actions"><button data-device-control="poster-call" class="call-button" onclick={() => command('dial')} disabled={!session.callId || !account.signedIn}>☎ Call</button><button data-device-control="poster-message" onclick={() => command('message')} disabled={!session.callId}>Message</button></div><small>Authored poster from the original Contacts card; actual canonical Calls recent.</small></aside>{/if}</div>
   {:else if session.tab === 'settings'}
    <button data-device-control="shared-account" onclick={() => command('account.open')}>Manage Shared Account…</button>
    <h1>Calls Settings</h1><p>One canonical Calls preference source, shared with {windows ? 'Teams' : 'FaceTime'}.</p><div class="phone-settings"><label><input data-device-control="notifications" type="checkbox" checked={shared.calls.preferences.notificationsEnabled} onchange={event => preference('notificationsEnabled',event.currentTarget.checked)} /> Local call notifications</label><label>Default kind <select data-device-control="default-kind" value={shared.calls.preferences.defaultKind} onchange={event => preference('defaultKind',event.currentTarget.value)}><option value="audio">Audio</option><option value="video">Video</option></select></label><label>Ringtone presentation <select data-device-control="ringtone" value={shared.calls.preferences.ringtone} onchange={event => preference('ringtone',event.currentTarget.value)}><option>Opening</option><option>Reflection</option></select></label><label><input data-device-control="hide-self" type="checkbox" checked={shared.calls.preferences.hideSelfView} onchange={event => preference('hideSelfView',event.currentTarget.checked)} /> Hide authored self view</label><h2>Blocked endpoints</h2>{#each shared.messages.blockedAddresses as address}<div>{address}<button data-device-control={'unblock:' + address} onclick={() => command('unblock',{address})}>Unblock</button></div>{/each}{#if !shared.messages.blockedAddresses.length}<p>No blocked scene endpoints.</p>{/if}</div>
   {:else if session.tab === 'messages'}
    <h1>Messages</h1>{#if !conversation}<div class="phone-list">{#each shared.messages.conversations as row}<button data-device-control={'conversation:' + row.id} onclick={() => command('conversation.select', { conversationId: row.id })}><span class="avatar" style:background={row.tint}>{row.initials}</span><span><b>{row.name}</b><small>{row.items.at(-1)?.text ?? row.items.at(-1)?.label ?? 'Shared conversation'}</small></span></button>{/each}</div>{:else}<button data-device-control="conversations" onclick={() => command('tab.set',{tab:'messages'})}>‹ Conversations</button><h2>{conversation.name}</h2><div class="phone-messages">{#each conversation.items as item}<div class:outgoing={item.direction === 'outgoing'} data-shared-message={item.id}>{#if item.kind === 'text'}{item.text}{:else if item.kind === 'image'}<img src={`${profile.assets?.messages ?? '/messages'}/${item.asset}`} alt={item.label} />{:else if item.kind === 'emoji'}{#each item.assets as image}<img class="phone-message-emoji" src={`${profile.assets?.messages ?? '/messages'}/${image.asset}`} alt={image.label} />{/each}{:else}<span>Shared route message</span>{/if}{#each item.reactions ?? [] as reaction}<small title={reaction.participant}>{reaction.emoji}</small>{/each}</div>{/each}</div><form class="message-compose" onsubmit={event => { event.preventDefault(); command('message.send'); }}><input data-device-control="message-body" aria-label="Message text" placeholder="Local message" value={session.body} maxlength="65536" oninput={event => input('message.set','body',event)} /><button data-device-control="send" disabled={!session.body.trim() || !account.signedIn}>↑</button></form>{/if}
   {:else if session.tab === 'photos'}
    <h1>Photos</h1>{#if photo}<button data-device-control="photos-back" onclick={() => command('tab.set',{tab:'photos'})}>‹ Library</button><h2>{photo.title}</h2>{#if photo.mime.startsWith('image/')}<img class="phone-photo" src={photo.editedContent ?? photo.content} alt={photo.title} />{:else}<video class="phone-photo" data-device-photo-media aria-label={photo.title} src={photo.content} preload="metadata"></video><div class="actions"><button data-device-control="video-play" onclick={() => command('photo.playback',{action:'play'})}>Play</button><button data-device-control="video-pause" onclick={() => command('photo.playback',{action:'pause'})}>Pause</button><label>Seek <input data-device-control="video-seek" type="range" min="0" max={photo.duration} step="0.1" value="0" aria-label="Seek authored video" onchange={event => command('photo.playback',{action:'seek',position:Number(event.currentTarget.value)})} /></label></div>{/if}<small>Original shared Photos item {photo.id} · revision {photo.revision}</small>{:else}<div class="phone-photo-grid">{#each photos as item}<button data-device-control={'photo:' + item.id} onclick={() => command('photo.select',{photoId:item.id})}>{#if item.mime.startsWith('image/')}<img src={item.editedContent ?? item.content} alt={item.title} />{:else}<span>▶ {item.title}</span>{/if}</button>{/each}</div>{/if}
   {/if}
   {#if activeCall}<section class="phone-active-call"><strong>{activeCall.participants.map(row => row.name).join(', ')}</strong><span>{activeCall.status} · {activeCall.muted ? 'Muted' : 'Local authored audio'}</span><button data-device-control="mute" onclick={() => command('mute',{muted:!activeCall.muted})}>{activeCall.muted ? 'Unmute' : 'Mute'}</button><button class="end-call" data-device-control="end-call" onclick={() => command('end')}>End Call</button></section>{/if}
   {#if mirroring && session.tab !== 'home'}<nav class="phone-tabs">{#each ['recents','contacts','keypad','messages','photos'] as tab}<button data-device-control={'tab:' + tab} class:selected={session.tab === tab} onclick={() => command('tab.set',{tab})}>{tab[0].toUpperCase() + tab.slice(1)}</button>{/each}</nav>{/if}
  </main>
 </div>
 {/if}
 {#if session.sheet === 'help'}<div class="device-sheet" role="dialog" aria-modal="true" aria-label="Local device help"><h2>{mirroring ? 'iPhone Mirroring' : 'Phone'} — Local Device</h2><p>{disclosure}</p><p>Phone uses the one canonical Calls ledger and the exact selected Contacts phone value. Favorites are window UI references, not copied cards. Messages sends publish genuine local Messages items through the Root native composer. Photos reads original shared image/video bytes.</p><p>Fictional passcode 482316. Pairing and availability come from the original scene Bluetooth device; account identity comes from shared Messages. No host credentials, permissions, telephony or screen transport.</p><button data-device-control="help-close" onclick={() => command('sheet.open',{sheet:'none'})}>Done</button></div>{/if}
 {/if}
 {#if error}<div class="device-error" role="alert">{error}</div>{/if}
 <footer class="device-disclosure">{disclosure}</footer>
</section>
